    pub(crate) fn assert_valid_credential_envelope(
        credential: Credential,
        expected_claim_root: [u8; 32],
    ) -> Result<(), CompactError> {
        compact_assert!((credential.version == 1), "Credential version mismatch");
        compact_assert!(
            (credential.claimRoot == expected_claim_root),
            "Credential claim root mismatch"
        );
        Ok(if credential.hasExpiration {
            let t = credential.expiresAt;
            compact_assert!((t >= credential.issuedAt), "Expiration must not precede issuance");
        })
    }

